/* @autogenerated */
package net.civeira.phylax.features.oauth.client.application;

import java.time.Duration;
import java.time.Instant;
import java.util.Collection;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.oauth.client.domain.ClientDetails;
import net.civeira.phylax.features.oauth.client.domain.exception.RequestObjectException;
import net.civeira.phylax.features.oauth.client.domain.gateway.ClientJwtSignatureGateway;
import net.civeira.phylax.features.oauth.client.domain.gateway.JwtReplayGateway;

/**
 * Verifies a signed request object (JAR, RFC 9101, task 3.3) and turns it into authorization
 * parameters.
 *
 * <ul>
 * <li>Signed with a key the client registered and its registered algorithm ({@code RS256} or
 * {@code ES256}); unsigned ({@code none}) or symmetric objects are rejected.</li>
 * <li>{@code iss} and {@code client_id} are the client; {@code aud} includes the issuer of the
 * tenant.</li>
 * <li>{@code exp} is required and in the future, {@code nbf} is not in the future, and the object
 * lives at most an hour.</li>
 * <li>{@code jti} is required and used only once (anti-replay, shared with client assertions).</li>
 * <li>A request object cannot carry {@code request} or {@code request_uri}.</li>
 * </ul>
 * Only the parameters of the object count: the caller ignores the rest of the query, except a
 * {@code client_id} that must match.
 */
@ApplicationScoped
@RequiredArgsConstructor
public class RequestObjectVerifier {

  public static final String PURPOSE = "request_object";
  private static final Duration MAX_LIFETIME = Duration.ofHours(1);
  private static final Duration SKEW = Duration.ofSeconds(60);

  private final ClientJwtSignatureGateway signatures;
  private final JwtReplayGateway replays;

  /**
   * Verifies a request object.
   *
   * @param tenant tenant of the endpoint
   * @param issuer issuer of the tenant, the expected audience
   * @param client client that signed it
   * @param jwt compact request object
   * @return authorization parameters
   * @throws RequestObjectException invalid_request_object
   */
  public Map<String, String> verify(String tenant, String issuer, ClientDetails client,
      String jwt) {
    Map<String, Object> claims = signatures.verify(client, jwt)
        .orElseThrow(() -> RequestObjectException.invalid("Invalid request object signature"));
    String clientId = client.getClientId();
    if (!clientId.equals(claims.get("iss"))) {
      throw RequestObjectException.invalid("iss must be the client");
    }
    if (claims.containsKey("client_id") && !clientId.equals(claims.get("client_id"))) {
      throw RequestObjectException.invalid("client_id does not match");
    }
    if (!audiences(claims.get("aud")).contains(issuer)) {
      throw RequestObjectException.invalid("aud must include the issuer");
    }
    if (claims.containsKey("request") || claims.containsKey("request_uri")) {
      throw RequestObjectException.invalid("A request object cannot nest another one");
    }
    Instant now = Instant.now();
    Instant exp = instant(claims.get("exp"));
    if (exp == null || !exp.isAfter(now)) {
      throw RequestObjectException.invalid("Expired or without exp");
    }
    Instant nbf = instant(claims.get("nbf"));
    if (nbf != null && nbf.isAfter(now.plus(SKEW))) {
      throw RequestObjectException.invalid("Not valid yet");
    }
    Instant start = nbf != null ? nbf : instant(claims.get("iat"));
    if (Duration.between(start != null ? start : now, exp).compareTo(MAX_LIFETIME) > 0) {
      throw RequestObjectException.invalid("Lifetime longer than an hour");
    }
    Object jti = claims.get("jti");
    if (!(jti instanceof String id) || id.isBlank()) {
      throw RequestObjectException.invalid("jti is required");
    }
    if (!replays.firstUse(tenant, clientId, PURPOSE, id, exp)) {
      throw RequestObjectException.invalid("Request object already used");
    }
    return parameters(claims, clientId);
  }

  private static Map<String, String> parameters(Map<String, Object> claims, String clientId) {
    Map<String, String> params = new LinkedHashMap<>();
    claims.forEach((name, value) -> {
      if (List.of("iss", "aud", "exp", "nbf", "iat", "jti").contains(name) || value == null) {
        return;
      }
      if (value instanceof Collection<?> values) {
        params.put(name, values.stream().map(String::valueOf)
            .collect(Collectors.joining("audience".equals(name) ? "," : " ")));
      } else {
        params.put(name, String.valueOf(value));
      }
    });
    params.put("client_id", clientId);
    return params;
  }

  private static List<String> audiences(Object aud) {
    if (aud instanceof String single) {
      return List.of(single);
    }
    if (aud instanceof Collection<?> values) {
      return values.stream().map(String::valueOf).toList();
    }
    return List.of();
  }

  private static Instant instant(Object value) {
    if (value instanceof Number seconds) {
      return Instant.ofEpochSecond(seconds.longValue());
    }
    if (value instanceof java.util.Date date) {
      return date.toInstant();
    }
    return null;
  }
}
